import java.util.*;
import java.util.function.LongSupplier;

public class Solution {
    enum TamanhoVaga { MOTO, CARRO, GRANDE }

    enum TipoVeiculo {
        MOTO(TamanhoVaga.MOTO), CARRO(TamanhoVaga.CARRO), VAN(TamanhoVaga.GRANDE);

        final TamanhoVaga minimo;

        TipoVeiculo(TamanhoVaga minimo) {
            this.minimo = minimo;
        }
    }

    record Ticket(String id, String placa, String vagaId, TamanhoVaga tamanho, long entradaMillis) {}

    interface Tarifa {
        long calcularCentavos(long duracaoMillis, TamanhoVaga vaga);
    }

    static class TarifaPorHora implements Tarifa {
        static final long TOLERANCIA = 15 * 60_000L;
        static final long HORA = 60 * 60_000L;
        private final Map<TamanhoVaga, Long> centavosPorHora;

        TarifaPorHora(Map<TamanhoVaga, Long> centavosPorHora) {
            for (TamanhoVaga t : TamanhoVaga.values()) {
                if (!centavosPorHora.containsKey(t)) throw new IllegalArgumentException("sem preco para " + t);
            }
            this.centavosPorHora = new EnumMap<>(centavosPorHora);
        }

        @Override
        public long calcularCentavos(long duracaoMillis, TamanhoVaga vaga) {
            if (duracaoMillis <= TOLERANCIA) return 0;
            long horasIniciadas = (duracaoMillis + HORA - 1) / HORA; // ceil sem ponto flutuante
            return horasIniciadas * centavosPorHora.get(vaga);
        }
    }

    // entrar/sair: O(log n) no número de vagas. Espaço: O(n).
    static class Estacionamento {
        private record Vaga(int andar, int indice, TamanhoVaga tamanho) {
            String id() {
                return andar + "-" + tamanho + "-" + indice;
            }
        }

        private static final Comparator<Vaga> ORDEM =
                Comparator.comparingInt(Vaga::andar).thenComparingInt(Vaga::indice);

        private final Map<TamanhoVaga, TreeSet<Vaga>> livres = new EnumMap<>(TamanhoVaga.class);
        private final Map<String, Ticket> ativosPorId = new HashMap<>();
        private final Map<String, Vaga> vagaPorTicket = new HashMap<>();
        private final Map<String, String> ticketPorPlaca = new HashMap<>();
        private final Tarifa tarifa;
        private final LongSupplier relogio;
        private long sequencia;

        Estacionamento(int andares, int motoPorAndar, int carroPorAndar, int grandePorAndar,
                       Tarifa tarifa, LongSupplier relogio) {
            if (andares < 1 || motoPorAndar < 0 || carroPorAndar < 0 || grandePorAndar < 0) {
                throw new IllegalArgumentException("configuracao invalida");
            }
            this.tarifa = Objects.requireNonNull(tarifa);
            this.relogio = Objects.requireNonNull(relogio);
            Map<TamanhoVaga, Integer> porAndar = Map.of(
                    TamanhoVaga.MOTO, motoPorAndar,
                    TamanhoVaga.CARRO, carroPorAndar,
                    TamanhoVaga.GRANDE, grandePorAndar);
            for (TamanhoVaga t : TamanhoVaga.values()) {
                TreeSet<Vaga> set = new TreeSet<>(ORDEM);
                for (int andar = 1; andar <= andares; andar++) {
                    for (int i = 1; i <= porAndar.get(t); i++) set.add(new Vaga(andar, i, t));
                }
                livres.put(t, set);
            }
        }

        Ticket entrar(String placa, TipoVeiculo tipo) {
            if (placa == null || placa.isBlank() || tipo == null) throw new IllegalArgumentException("placa e tipo obrigatorios");
            if (ticketPorPlaca.containsKey(placa)) throw new IllegalStateException("veiculo ja esta no estacionamento");
            for (TamanhoVaga t : TamanhoVaga.values()) {
                if (t.ordinal() < tipo.minimo.ordinal()) continue;
                Vaga vaga = livres.get(t).pollFirst();
                if (vaga == null) continue;
                Ticket ticket = new Ticket("T" + (++sequencia), placa, vaga.id(), t, relogio.getAsLong());
                ativosPorId.put(ticket.id(), ticket);
                vagaPorTicket.put(ticket.id(), vaga);
                ticketPorPlaca.put(placa, ticket.id());
                return ticket;
            }
            throw new IllegalStateException("lotado");
        }

        long sair(String ticketId) {
            Ticket ticket = ativosPorId.remove(ticketId);
            if (ticket == null) throw new IllegalArgumentException("ticket invalido ou ja encerrado: " + ticketId);
            Vaga vaga = vagaPorTicket.remove(ticketId);
            ticketPorPlaca.remove(ticket.placa());
            livres.get(vaga.tamanho()).add(vaga);
            return tarifa.calcularCentavos(relogio.getAsLong() - ticket.entradaMillis(), vaga.tamanho());
        }

        int vagasLivres(TamanhoVaga tamanho) {
            return livres.get(tamanho).size();
        }

        Optional<Ticket> ticketDaPlaca(String placa) {
            String id = ticketPorPlaca.get(placa);
            return id == null ? Optional.empty() : Optional.of(ativosPorId.get(id));
        }
    }
}

