import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.time.Duration;
import java.util.Map;
import java.util.Optional;

class SolutionTest {
    static final long MIN = 60_000L;
    final long[] agora = {0};
    final Solution.Tarifa tarifa = new Solution.TarifaPorHora(Map.of(
            Solution.TamanhoVaga.MOTO, 500L,
            Solution.TamanhoVaga.CARRO, 1_000L,
            Solution.TamanhoVaga.GRANDE, 2_000L));

    Solution.Estacionamento est(int andares, int moto, int carro, int grande) {
        return new Solution.Estacionamento(andares, moto, carro, grande, tarifa, () -> agora[0]);
    }

    @Test void escolheMenorVagaCompativel() {
        var e = est(1, 1, 1, 1);
        assertEquals("1-MOTO-1", e.entrar("M1", Solution.TipoVeiculo.MOTO).vagaId());
        assertEquals("1-CARRO-1", e.entrar("M2", Solution.TipoVeiculo.MOTO).vagaId());
        assertEquals("1-GRANDE-1", e.entrar("C1", Solution.TipoVeiculo.CARRO).vagaId());
        var ex = assertThrows(IllegalStateException.class, () -> e.entrar("V1", Solution.TipoVeiculo.VAN));
        assertEquals("lotado", ex.getMessage());
    }

    @Test void vanSoEmVagaGrande() {
        var e = est(1, 5, 5, 0);
        assertThrows(IllegalStateException.class, () -> e.entrar("V1", Solution.TipoVeiculo.VAN));
        assertEquals(5, e.vagasLivres(Solution.TamanhoVaga.CARRO));
    }

    @Test void menorAndarEMenorIndice() {
        var e = est(2, 0, 2, 0);
        assertEquals("1-CARRO-1", e.entrar("A", Solution.TipoVeiculo.CARRO).vagaId());
        assertEquals("1-CARRO-2", e.entrar("B", Solution.TipoVeiculo.CARRO).vagaId());
        assertEquals("2-CARRO-1", e.entrar("C", Solution.TipoVeiculo.CARRO).vagaId());
    }

    @Test void saidaLiberaAVagaParaReuso() {
        var e = est(2, 0, 2, 0);
        var a = e.entrar("A", Solution.TipoVeiculo.CARRO);
        e.entrar("B", Solution.TipoVeiculo.CARRO);
        e.sair(a.id());
        assertEquals(3, e.vagasLivres(Solution.TamanhoVaga.CARRO));
        assertEquals("1-CARRO-1", e.entrar("C", Solution.TipoVeiculo.CARRO).vagaId());
    }

    @Test void ticketsSequenciais() {
        var e = est(1, 0, 3, 0);
        assertEquals("T1", e.entrar("A", Solution.TipoVeiculo.CARRO).id());
        assertEquals("T2", e.entrar("B", Solution.TipoVeiculo.CARRO).id());
    }

    @Test void placaDuplicadaEPlacaQueVoltou() {
        var e = est(1, 0, 3, 0);
        var t = e.entrar("ABC1D23", Solution.TipoVeiculo.CARRO);
        assertThrows(IllegalStateException.class, () -> e.entrar("ABC1D23", Solution.TipoVeiculo.CARRO));
        assertEquals(Optional.of(t), e.ticketDaPlaca("ABC1D23"));
        e.sair(t.id());
        assertEquals(Optional.empty(), e.ticketDaPlaca("ABC1D23"));
        assertDoesNotThrow(() -> e.entrar("ABC1D23", Solution.TipoVeiculo.CARRO));
    }

    @Test void toleranciaECobrancaPorHoraIniciada() {
        var e = est(1, 0, 5, 0);
        var t1 = e.entrar("A", Solution.TipoVeiculo.CARRO);
        agora[0] = 15 * MIN;
        assertEquals(0, e.sair(t1.id()));

        var t2 = e.entrar("B", Solution.TipoVeiculo.CARRO);
        agora[0] += 15 * MIN + 1;
        assertEquals(1_000, e.sair(t2.id()));

        var t3 = e.entrar("C", Solution.TipoVeiculo.CARRO);
        agora[0] += 61 * MIN;
        assertEquals(2_000, e.sair(t3.id()));
    }

    @Test void pagaPeloTamanhoDaVagaOcupada() {
        var e = est(1, 0, 1, 0);
        var t = e.entrar("M1", Solution.TipoVeiculo.MOTO);
        assertEquals(Solution.TamanhoVaga.CARRO, t.tamanho());
        agora[0] = 30 * MIN;
        assertEquals(1_000, e.sair(t.id()));
    }

    @Test void ticketInvalidoOuReusado() {
        var e = est(1, 0, 1, 0);
        var t = e.entrar("A", Solution.TipoVeiculo.CARRO);
        e.sair(t.id());
        assertThrows(IllegalArgumentException.class, () -> e.sair(t.id()));
        assertThrows(IllegalArgumentException.class, () -> e.sair("T999"));
    }

    @Test void tarifaPlugavel() {
        Solution.Tarifa diaria = (duracao, vaga) -> 4_000L;
        var e = new Solution.Estacionamento(1, 0, 1, 0, diaria, () -> agora[0]);
        var t = e.entrar("A", Solution.TipoVeiculo.CARRO);
        assertEquals(4_000, e.sair(t.id()));
    }

    @Test void tarifaSemPrecoParaTodosOsTamanhos() {
        assertThrows(IllegalArgumentException.class,
                () -> new Solution.TarifaPorHora(Map.of(Solution.TamanhoVaga.CARRO, 1_000L)));
    }

    @Test void prediosGrandesNaoVarremTudo() {
        assertTimeout(Duration.ofSeconds(3), () -> {
            var e = est(100, 0, 1_000, 0);
            for (int i = 0; i < 100_000; i++) e.entrar("P" + i, Solution.TipoVeiculo.CARRO);
            assertEquals(0, e.vagasLivres(Solution.TamanhoVaga.CARRO));
            for (int i = 1; i <= 50_000; i++) e.sair("T" + i);
            assertEquals("1-CARRO-1", e.entrar("NOVO", Solution.TipoVeiculo.CARRO).vagaId());
        });
    }
}
